@torch.no_grad()
def generate(model, kind, noise):
    model.eval()
    images = model.decoder(noise) if kind == 'vae' else (model(noise) + 1) / 2
    return images.clamp(0, 1)


def save_grid(images, path, columns=8):
    images = images.detach().cpu().clamp(0, 1)
    rows = math.ceil(len(images) / columns)
    canvas = np.zeros((rows * 30, columns * 30), dtype=np.uint8)
    for i, sample in enumerate(images):
        row, col = divmod(i, columns)
        canvas[row * 30:row * 30 + 28, col * 30:col * 30 + 28] = (sample[0].numpy() * 255).round().astype(np.uint8)
    image = Image.fromarray(canvas)
    image.resize((canvas.shape[1] * 3, canvas.shape[0] * 3), Image.Resampling.NEAREST).save(path)

