@torch.no_grad()
def feature_mmd(a, b):
    # Unbiased squared MMD; finite samples may yield a slightly negative value.
    # L2-normalization fixes the kernel's scale across evaluator activations.
    a, b = F.normalize(a.double(), dim=1), F.normalize(b.double(), dim=1)
    aa, bb, ab = (a @ a.T + 1).pow(3), (b @ b.T + 1).pow(3), (a @ b.T + 1).pow(3)
    n, m = len(a), len(b)
    return ((aa.sum() - aa.trace()) / (n * (n - 1))
            + (bb.sum() - bb.trace()) / (m * (m - 1)) - 2 * ab.mean()).item()


@torch.no_grad()
def evaluate(model, kind, evaluator, reference, count=1024):
    rng = torch.Generator().manual_seed(9001)
    noise = torch.randn(count, LATENT, generator=rng)
    images = torch.cat([generate(model, kind, z) for z in noise.split(128)])
    features = torch.cat([evaluator.features(x) for x in images.split(128)])
    predicted = evaluator.classifier(features).argmax(1)
    histogram = torch.bincount(predicted, minlength=10).float()
    probabilities = histogram / count
    entropy = -(probabilities * probabilities.clamp_min(1e-12).log()).sum().item()
    return {'feature_mmd': feature_mmd(features, reference[:count]),
            'entropy': entropy, 'coverage': int((histogram > 0).sum()),
            'digit_counts': histogram.int().tolist(), 'sample_count': count}
